<?php
require_once __DIR__ . '/auth.php';requireLogin();
$pdo=db();$uid=userId();$kind=$settlementType??'debt';$isDebt=$kind==='debt';$table=$isDebt?'debts':'receivables';$payTable=$isDebt?'debt_payments':'receivable_payments';$idCol=$isDebt?'debt_id':'receivable_id';$pageTitle=$isDebt?'Utang':'Piutang';$activePage=$isDebt?'utang.php':'piutang.php';$subject=$isDebt?'utang':'piutang';$actionVerb=$isDebt?'Bayar Cicilan':'Terima Pembayaran';
if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$action=$_POST['action']??'';if($action==='delete'){$st=$pdo->prepare("DELETE FROM {$table} WHERE id=? AND user_id=?");$st->execute([(int)$_POST['id'],$uid]);flash('success',ucfirst($subject).' berhasil dihapus.');redirect($activePage);}if($action==='save'){$id=(int)($_POST['id']??0);$name=trim((string)$_POST['name']);$total=parseAmount($_POST['total_amount']??0);$paid=parseAmount($_POST['paid_amount']??0);$due=(string)($_POST['due_date']??'');$desc=trim((string)$_POST['description']);$status=$paid<=0?'Belum Lunas':($paid>=$total?'Lunas':'Sebagian');if($name===''||$total<=0||$paid<0||!validDate($due)){flash('error','Lengkapi nama, nominal, dan jatuh tempo.');redirect($activePage.'?action='.($id?'edit&id='.$id:'add'));}$paid=min($paid,$total);if($id){$st=$pdo->prepare("UPDATE {$table} SET name=?,total_amount=?,paid_amount=?,due_date=?,description=?,status=? WHERE id=? AND user_id=?");$st->execute([$name,$total,$paid,$due,$desc,$status,$id,$uid]);}else{$st=$pdo->prepare("INSERT INTO {$table}(user_id,name,total_amount,paid_amount,due_date,description,status) VALUES(?,?,?,?,?,?,?)");$st->execute([$uid,$name,$total,$paid,$due,$desc,$status]);}flash('success',ucfirst($subject).' berhasil disimpan.');redirect($activePage);}if($action==='pay'){$id=(int)$_POST['item_id'];$amount=parseAmount($_POST['amount']??0);$date=(string)$_POST['payment_date'];$desc=trim((string)$_POST['description']);$st=$pdo->prepare("SELECT total_amount,paid_amount FROM {$table} WHERE id=? AND user_id=?");$st->execute([$id,$uid]);$item=$st->fetch();$remaining=$item?(float)$item['total_amount']-(float)$item['paid_amount']:0;if(!$item||$amount<=0||$amount>$remaining||!validDate($date)){flash('error','Nominal pembayaran tidak valid atau melebihi sisa.');redirect($activePage);}else{$pdo->beginTransaction();$st=$pdo->prepare("INSERT INTO {$payTable}({$idCol},amount,payment_date,description) VALUES(?,?,?,?)");$st->execute([$id,$amount,$date,$desc]);$newPaid=(float)$item['paid_amount']+$amount;$status=$newPaid>=$item['total_amount']?'Lunas':'Sebagian';$st=$pdo->prepare("UPDATE {$table} SET paid_amount=?,status=? WHERE id=? AND user_id=?");$st->execute([$newPaid,$status,$id,$uid]);$pdo->commit();flash('success',$actionVerb.' berhasil dicatat.');redirect($activePage.'?history='.$id);}}}
$st=$pdo->prepare("SELECT * FROM {$table} WHERE user_id=? ORDER BY status='Lunas',due_date IS NULL,due_date");$st->execute([$uid]);$rows=$st->fetchAll();$edit=null;if(($_GET['action']??'')==='edit'){$st=$pdo->prepare("SELECT * FROM {$table} WHERE id=? AND user_id=?");$st->execute([(int)$_GET['id'],$uid]);$edit=$st->fetch()?:null;}if(($_GET['action']??'')==='add')$edit=['id'=>0,'name'=>'','total_amount'=>'','paid_amount'=>'','due_date'=>date('Y-m-d',strtotime('+30 days')),'description'=>''];$selected=(int)($_GET['history']??0);$history=[];if($selected){$st=$pdo->prepare("SELECT p.*,x.name FROM {$payTable} p JOIN {$table} x ON x.id=p.{$idCol} WHERE p.{$idCol}=? AND x.user_id=? ORDER BY p.payment_date DESC,p.id DESC");$st->execute([$selected,$uid]);$history=$st->fetchAll();}$user=currentUser($pdo);require __DIR__.'/header.php';
?><div class="page-heading"><div><p class="eyebrow">Kewajiban dan hak finansial</p><h1><?=e($pageTitle)?></h1><p>Kelola <?=e($subject)?> dan catat setiap pembayaran agar sisanya selalu jelas.</p></div><a class="btn btn-primary" href="?action=add"><i data-lucide="plus"></i> Tambah <?=e(ucfirst($subject))?></a></div>
<section class="grid-two"><?php if(!$rows):?><div class="card empty-state" style="grid-column:1/-1"><div class="empty-icon"><i data-lucide="<?=$isDebt?'credit-card':'hand-coins'?>"></i></div><strong>Belum ada <?=e($subject)?>.</strong><p>Tambahkan catatan agar komitmen finansialmu mudah dipantau.</p><a class="btn btn-primary btn-sm" href="?action=add">Tambah <?=e(ucfirst($subject))?></a></div><?php else:?><?php foreach($rows as $row):$remaining=max(0,(float)$row['total_amount']-(float)$row['paid_amount']);$pct=percentage((float)$row['paid_amount'],(float)$row['total_amount']);$overdue=$row['due_date']&&$row['due_date']<date('Y-m-d')&&$row['status']!=='Lunas';?><article class="card"><div class="card-header"><div><span class="badge <?=$row['status']==='Lunas'?'success':($overdue?'danger':'warning')?>"><?=e($overdue?'Terlambat':$row['status'])?></span><h2 class="card-title" style="margin-top:10px"><?=e($row['name'])?></h2><p class="card-subtitle">Jatuh tempo <?=e(date('d/m/Y',strtotime($row['due_date'])))?></p></div><div class="actions"><a class="btn btn-ghost btn-sm icon-btn" href="?action=edit&id=<?=(int)$row['id']?>"><i data-lucide="pencil"></i></a><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$row['id']?>"><button class="btn btn-ghost btn-sm icon-btn" data-confirm="Hapus catatan ini?" type="submit"><i data-lucide="trash-2"></i></button></form></div></div><div class="stat-value"><?=formatRupiah($remaining)?></div><div class="progress-meta"><span>Sudah <?=$isDebt?'dibayar':'diterima'?> <?=formatRupiah($row['paid_amount'])?></span><strong><?=number_format($pct,1,',','.')?>%</strong></div><div class="progress-line"><div class="progress-fill <?=$row['status']==='Lunas'?'success':'warning'?>" style="width:<?=$pct?>%"></div></div><div class="modal-actions" style="justify-content:flex-start"><a class="btn btn-soft btn-sm" href="?history=<?=(int)$row['id']?>"><i data-lucide="history"></i> Riwayat</a><?php if($row['status']!=='Lunas'):?><button class="btn btn-primary btn-sm" data-open-modal="pay-<?=(int)$row['id']?>" type="button"><i data-lucide="hand-coins"></i> <?=e($actionVerb)?></button><?php endif;?></div></article><?php if($row['status']!=='Lunas'):?><div class="modal" id="pay-<?=(int)$row['id']?>"><div class="modal-head"><div><h3><?=e($actionVerb)?></h3><p>Sisa saat ini <?=formatRupiah($remaining)?>.</p></div><button class="icon-button" data-close-modal type="button"><i data-lucide="x"></i></button></div><form method="post" data-amount-form><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="pay"><input type="hidden" name="item_id" value="<?=(int)$row['id']?>"><div class="form-grid"><div class="form-field"><label>Nominal</label><input class="input" name="amount" data-amount required></div><div class="form-field"><label>Tanggal</label><input class="input" type="date" name="payment_date" value="<?=date('Y-m-d')?>" required></div><div class="form-field full"><label>Deskripsi</label><input class="input" name="description" placeholder="Contoh: cicilan bulan ini"></div></div><div class="modal-actions"><button class="btn btn-ghost" data-close-modal type="button">Batal</button><button class="btn btn-primary" type="submit">Simpan Pembayaran</button></div></form></div><?php endif;?><?php endforeach;?><?php endif;?></section>
<?php if($selected):?><section class="card"><div class="card-header"><div><h2 class="card-title">Riwayat Pembayaran</h2><p class="card-subtitle">Catatan pembayaran tersimpan</p></div><a class="btn btn-ghost btn-sm" href="<?=$activePage?>">Tutup</a></div><?php if(!$history):?><div class="empty-state">Belum ada histori.</div><?php else:?><div class="table-wrap"><table class="data-table"><thead><tr><th>Tanggal</th><th>Nama</th><th>Nominal</th><th>Deskripsi</th></tr></thead><tbody><?php foreach($history as $item):?><tr><td><?=e(date('d/m/Y',strtotime($item['payment_date'])))?></td><td><?=e($item['name'])?></td><td class="amount"><?=formatRupiah($item['amount'])?></td><td><?=e($item['description']?:'—')?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php endif;?>
<div class="modal <?=$edit?'is-open':''?>" id="settlement-modal"><div class="modal-head"><div><h3><?=$edit&&$edit['id']?'Edit':'Tambah'?> <?=e(ucfirst($subject))?></h3><p>Status dihitung otomatis dari nominal yang sudah dibayar/diterima.</p></div><button class="icon-button" data-close-modal type="button"><i data-lucide="x"></i></button></div><form method="post" data-amount-form><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="form-grid"><div class="form-field"><label>Nama</label><input class="input" name="name" value="<?=e($edit['name']??'')?>" placeholder="Nama pihak atau utang" required></div><div class="form-field"><label>Total</label><input class="input" name="total_amount" data-amount value="<?=e($edit['total_amount']??'')?>" required></div><div class="form-field"><label>Sudah <?=$isDebt?'dibayar':'diterima'?></label><input class="input" name="paid_amount" data-amount value="<?=e($edit['paid_amount']??'')?>" required></div><div class="form-field"><label>Jatuh tempo</label><input class="input" type="date" name="due_date" value="<?=e($edit['due_date']??'')?>" required></div><div class="form-field full"><label>Deskripsi</label><textarea class="textarea" name="description"><?=e($edit['description']??'')?></textarea></div></div><div class="modal-actions"><button class="btn btn-ghost" data-close-modal type="button">Batal</button><button class="btn btn-primary" type="submit">Simpan</button></div></form></div>
